code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[7] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 7:
                continue
            isolated = True
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                        isolated = False
            if isolated:
                for k in range(max(h, w)):
                    if r + k < h and c + k < w:
                        out[r + k][c + k] = color
                return out
    return out
'''
